#!/usr/bin/env python3
"""Enumerate sufficient coalitions on a finite score grid."""
from __future__ import annotations
from itertools import combinations, product
from typing import Callable
Profile = tuple[int, ...]
Rule = Callable[[Profile], int]

def coalitions(n: int) -> list[frozenset[int]]:
    return [frozenset(s) for r in range(n + 1) for s in combinations(range(n), r)]

def depends(rule: Rule, support: frozenset[int], grid: list[Profile]) -> bool:
    return all(rule(x) == rule(y) for x in grid for y in grid
               if all(x[i] == y[i] for i in support))

def projection(d: int) -> Rule:
    return lambda x: x[d]

def run() -> None:
    grid = list(product(range(3), repeat=2))
    rules: list[tuple[str, Rule]] = [("projection 1", projection(0)), ("minimum", min)]
    for name, rule in rules:
        sufficient = [sorted(i + 1 for i in s) for s in coalitions(2) if depends(rule, s, grid)]
        print(f"{name}: sufficient coalitions = {sufficient}")
if __name__ == "__main__":
    run()

