from __future__ import annotations
from itertools import product
from typing import Callable, Iterable, Sequence
Profile = tuple[float, ...]
Rule = Callable[[Profile], float]

def verify_weak_tropical_laws(rule: Rule, profiles: Sequence[Profile],
                               constants: Iterable[float], tol: float = 1e-10) -> dict[str, bool]:
    def meet(x: Profile, y: Profile) -> Profile:
        return tuple(min(a, b) for a, b in zip(x, y))
    min_ok = all(abs(rule(meet(x, y)) - min(rule(x), rule(y))) <= tol
                 for x in profiles for y in profiles)
    trans_ok = all(abs(rule(tuple(a + c for a in x)) - rule(x) - c) <= tol
                   for x in profiles for c in constants)
    norm_ok = bool(profiles) and abs(rule(tuple(0.0 for _ in profiles[0]))) <= tol
    return {"min_preservation": min_ok, "translation_equivariance": trans_ok,
            "normalization": norm_ok}

if __name__ == "__main__":
    grid = [tuple(p) for p in product((-1.0, 0.0, 1.0), repeat=2)]
    print(verify_weak_tropical_laws(min, grid, (-2.0, 0.0, 3.0)))

from __future__ import annotations
from itertools import combinations, product
from typing import Callable, Sequence
Profile = tuple[float, ...]
Rule = Callable[[Profile], float]

def sufficient_coalitions(rule: Rule, profiles: Sequence[Profile]) -> list[frozenset[int]]:
    n = len(profiles[0])
    answer: list[frozenset[int]] = []
    for size in range(n + 1):
        for indices in combinations(range(n), size):
            coalition = frozenset(indices)
            buckets: dict[tuple[float, ...], float] = {}
            valid = True
            for x in profiles:
                key = tuple(x[i] for i in indices)
                value = rule(x)
                if key in buckets and buckets[key] != value:
                    valid = False
                    break
                buckets[key] = value
            if valid:
                answer.append(coalition)
    return answer

if __name__ == "__main__":
    grid = [tuple(map(float, p)) for p in product(range(3), repeat=2)]
    print(sufficient_coalitions(min, grid))

from __future__ import annotations
from typing import Callable
Profile = tuple[float, ...]
Rule = Callable[[Profile], float]

def identify_projection(rule: Rule, voters: int) -> int | None:
    """Identify a coordinate projection using separating profiles, or return None."""
    zero = tuple(0.0 for _ in range(voters))
    if rule(zero) != 0.0:
        return None
    candidates: list[int] = []
    for d in range(voters):
        consistent = True
        for j in range(voters):
            profile = tuple(1.0 if i == j else 0.0 for i in range(voters))
            if rule(profile) != profile[d]:
                consistent = False
                break
        if consistent:
            candidates.append(d)
    return candidates[0] if len(candidates) == 1 else None

if __name__ == "__main__":
    print("projection selected:", identify_projection(lambda x: x[1], 3))
    print("minimum selected:", identify_projection(min, 3))

